def busy_drive_letters() -> set:
    """Acik disklere ait surucu harfleri (buyuk harf, iki nokta olmadan)."""
    letters = set()
    for info in open_device_paths().values():
        for item in info.mounted:
            head = _drive_letter(item)
            if head:
